// Generates the Swift and TypeScript protocol models from schemas/:
//
//   node scripts/generate-protocol.mjs          write the generated files
//   node scripts/generate-protocol.mjs --check  exit 1 if they're out of date
//
// Only the shape is generated: types, their fields, Codable conformance and
// initializers. Validation and helpers stay handwritten, as Swift extensions
// and TypeScript code beside the generated file.
//
// Annotations the schemas use (validators ignore them):
//   x-name             the type's name in both languages
//   x-swift-name       / x-ts-name: a different name in one language
//   x-swift-type       a Swift type to use instead of a generated one (an enum kept as String)
//   x-swift-default    a Swift expression for the initializer default, when `default` can't say it
//   x-swift-conforms   extra Swift protocols, such as Identifiable
//   x-swift-external   the type is written by hand in Swift (JSONValue)
//   x-swift-list       on an enum kept as String: also emit its values as `Namespace.name`
//   x-ts-type          the TypeScript type, written out (JSONValue)
//   x-discriminator-name  on a `oneOf` of objects: they become one type with
//                      every field, and the field each variant fixes with `const`
//                      becomes an enum of that name
// `default` becomes the Swift initializer's default; `description` becomes a doc comment.
import { readFile, writeFile } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
export const schemaFiles = ["schemas/protocol.schema.json", "schemas/connections.schema.json", "schemas/manifest.schema.json"];
export const outputs = { swift: "native/NotchProtocol/Sources/Generated.swift", ts: "packages/protocol/src/generated.ts" };
const header = (comment) => `${comment} Generated by scripts/generate-protocol.mjs from ${schemaFiles.join(", ")}.\n${comment} Don't edit; change the schema and run \`node scripts/generate-protocol.mjs\`.\n`;

const swiftKeywords = new Set(["default", "repeat", "case", "class", "enum", "extension", "func", "import", "init", "let", "operator",
  "protocol", "static", "struct", "subscript", "typealias", "var", "break", "continue", "do", "else", "for", "if", "in", "return",
  "switch", "where", "while", "as", "is", "nil", "self", "Self", "super", "throw", "throws", "true", "false", "try", "Type"]);
const swiftIdentifier = (name) => (swiftKeywords.has(name) ? `\`${name}\`` : name);

/**
 * Merges a named `oneOf` of objects into one object type: fields that only
 * some variants have become optional, and the field every variant fixes with
 * `const` becomes an enum named by `x-discriminator-name`.
 */
function flatten(node) {
  const variants = node.oneOf;
  if (!variants.every((variant) => variant.type === "object")) throw new Error(`${node["x-name"]}: only a oneOf of objects can be merged`);
  const properties = {};
  for (const variant of variants) for (const [name, property] of Object.entries(variant.properties ?? {})) properties[name] ??= property;
  const discriminator = Object.keys(properties).find((name) => variants.every((variant) => variant.properties?.[name]?.const !== undefined));
  if (discriminator) {
    if (!node["x-discriminator-name"]) throw new Error(`${node["x-name"]}: add x-discriminator-name for ${discriminator}`);
    properties[discriminator] = { "x-name": node["x-discriminator-name"], enum: variants.map((variant) => variant.properties[discriminator].const) };
  }
  node.type = "object";
  node.properties = properties;
  node.required = Object.keys(properties).filter((name) => variants.every((variant) => variant.required?.includes(name)));
  delete node.oneOf;
}

/**
 * Collects every named type in the schemas, in a stable order: definitions
 * first as they appear, with the named types nested in each definition after it.
 */
export function collect(schemas) {
  const types = [];
  const byNode = new Map();
  const resolveRef = (schema, ref) => {
    const match = /^#\/\$defs\/(.+)$/.exec(ref);
    if (!match || !schema.$defs?.[match[1]]) throw new Error(`Unknown reference ${ref}`);
    return schema.$defs[match[1]];
  };
  /** The node a property's type comes from: a `$ref` target, or the first `allOf` reference. */
  const target = (schema, node) => {
    if (node.$ref) return target(schema, resolveRef(schema, node.$ref));
    if (node.allOf?.[0]?.$ref && !node["x-name"]) return target(schema, resolveRef(schema, node.allOf[0].$ref));
    return node;
  };
  const visit = (schema, node) => {
    if (!node || typeof node !== "object") return;
    if (node["x-discriminator-name"] && node.oneOf) flatten(node);
    if (node["x-name"] || node["x-swift-name"] || node["x-ts-name"]) {
      if (!byNode.has(node)) {
        const kind = node.enum ? "enum" : node.type === "object" ? "struct" : node["x-ts-type"] ? "alias" : null;
        if (!kind) throw new Error(`${node["x-name"]}: only enums and objects can be named`);
        const type = { node, kind, swift: node["x-swift-name"] ?? node["x-name"], ts: node["x-ts-name"] ?? node["x-name"] };
        byNode.set(node, type);
        types.push(type);
      }
    }
    for (const value of Object.values(node.properties ?? {})) visit(schema, value);
    if (node.items) visit(schema, node.items);
  };
  for (const schema of schemas) {
    visit(schema, schema);
    for (const value of Object.values(schema.$defs ?? {})) visit(schema, value);
  }
  return { types, typeOf: (schema, node) => byNode.get(target(schema, node)), target };
}

function swiftType(context, schema, node) {
  const resolved = context.target(schema, node);
  if (resolved["x-swift-type"]) return resolved["x-swift-type"];
  const named = context.typeOf(schema, node);
  if (named) return named.swift;
  if (resolved.type === "array") return `[${swiftType(context, schema, resolved.items)}]`;
  if (resolved.type === "object" && resolved.additionalProperties && typeof resolved.additionalProperties === "object") {
    return `[String: ${swiftType(context, schema, resolved.additionalProperties)}]`;
  }
  switch (resolved.type) {
    case "string": return "String";
    case "integer": return "Int";
    case "number": return "Double";
    case "boolean": return "Bool";
  }
  if (typeof resolved.const === "number") return "Int";
  if (typeof resolved.const === "string") return "String";
  throw new Error(`No Swift type for ${JSON.stringify(node).slice(0, 120)}`);
}

function tsType(context, schema, node) {
  const resolved = context.target(schema, node);
  const named = context.typeOf(schema, node);
  if (named) return named.ts;
  if (resolved.const !== undefined) return JSON.stringify(resolved.const);
  if (resolved.enum) return resolved.enum.map((value) => JSON.stringify(value)).join(" | ");
  if (resolved.type === "array") {
    const item = tsType(context, schema, resolved.items);
    return /[ |]/.test(item) ? `(${item})[]` : `${item}[]`;
  }
  if (resolved.type === "object" && resolved.additionalProperties && typeof resolved.additionalProperties === "object") {
    return `Record<string, ${tsType(context, schema, resolved.additionalProperties)}>`;
  }
  if (resolved.type === "object") return `{ ${tsFields(context, schema, resolved).join(" ")} }`;
  if (Array.isArray(resolved.type)) return resolved.type.map((type) => tsType(context, schema, { type })).join(" | ");
  switch (resolved.type) {
    case "string": return "string";
    case "integer": case "number": return "number";
    case "boolean": return "boolean";
  }
  throw new Error(`No TypeScript type for ${JSON.stringify(node).slice(0, 120)}`);
}

function tsFields(context, schema, node) {
  const required = new Set(node.required ?? []);
  return Object.entries(node.properties ?? {}).map(([name, property]) => `${name}${required.has(name) ? "" : "?"}: ${tsType(context, schema, property)};`);
}

/** A Swift literal for a JSON Schema `default`. */
function swiftDefault(context, schema, property, value) {
  const resolved = context.target(schema, property);
  if (property["x-swift-default"] ?? resolved["x-swift-default"]) return property["x-swift-default"] ?? resolved["x-swift-default"];
  if (value === undefined) return undefined;
  const named = context.typeOf(schema, property);
  if (named?.kind === "enum" && !resolved["x-swift-type"]) return `.${swiftCase(value)}`;
  if (named?.kind === "struct" && value && typeof value === "object" && !Object.keys(value).length) return ".init()";
  if (Array.isArray(value) && !value.length) return "[]";
  return JSON.stringify(value);
}

const swiftCase = (value) => swiftIdentifier(value.replace(/[^A-Za-z0-9_]/g, "_"));
const doc = (text, indent, style) => {
  if (!text) return [];
  return style === "swift" ? text.split("\n").map((line) => `${indent}/// ${line}`) : [`${indent}/** ${text.replace(/\*\//g, "*\\/")} */`];
};

const sourceOf = (context, schemas, type) => schemas.find((schema) => {
  let found = false;
  const walk = (node) => {
    if (!node || typeof node !== "object" || found) return;
    if (node === type.node) { found = true; return; }
    Object.values(node.properties ?? {}).forEach(walk); walk(node.items); Object.values(node.$defs ?? {}).forEach(walk);
  };
  walk(schema);
  return found;
});

export function generateSwift(schemas) {
  const context = collect(schemas);
  const lines = [header("//").trimEnd(), "import Foundation", ""];
  for (const type of context.types) {
    const { node } = type;
    if (node["x-swift-list"]) {
      const [namespace, name] = node["x-swift-list"].split(".");
      lines.push(...doc(node.description ?? "Values an extension can list in its manifest, in display order.", "", "swift"));
      lines.push(`public enum ${namespace} {`, `    public static let ${name} = [`);
      lines.push(...node.enum.map((value) => `        ${JSON.stringify(value)},`), "    ]", "}", "");
    }
    if (node["x-swift-external"] || node["x-swift-type"]) continue;
    const schema = sourceOf(context, schemas, type);
    lines.push(...doc(node.description, "", "swift"));
    if (type.kind === "enum") {
      lines.push(`public enum ${type.swift}: String, Codable, Equatable, Sendable {`);
      for (const value of node.enum) {
        const name = swiftCase(value);
        lines.push(name.replace(/`/g, "") === value ? `    case ${name}` : `    case ${name} = ${JSON.stringify(value)}`);
      }
      lines.push("}", "");
      continue;
    }
    const conforms = ["Codable", "Equatable", ...(node["x-swift-conforms"] ?? []), "Sendable"];
    lines.push(`public struct ${type.swift}: ${conforms.join(", ")} {`);
    const required = new Set(node.required ?? []);
    const fields = Object.entries(node.properties ?? {}).map(([name, property]) => {
      const resolved = context.target(schema, property);
      const constant = resolved.const;
      const swift = swiftType(context, schema, property);
      // Only the protocol's JSON values tell null from absent; an x-swift-type JSONValue keeps the usual decoding.
      return { name, property, resolved, constant, swift, optional: !required.has(name), json: resolved["x-name"] === "JSONValue" };
    });
    for (const field of fields) {
      // A named inline type documents itself; the field only adds its own description.
      if (field.property.$ref || context.typeOf(schema, field.property)?.node !== field.property) lines.push(...doc(field.property.description, "    ", "swift"));
      if (field.constant !== undefined) lines.push(`    public var ${swiftIdentifier(field.name)} = ${JSON.stringify(field.constant)}`);
      else lines.push(`    public var ${swiftIdentifier(field.name)}: ${field.swift}${field.optional ? "?" : ""}`);
    }
    const parameters = fields.filter((field) => field.constant === undefined);
    const signature = parameters.map((field) => {
      const fallback = swiftDefault(context, schema, field.property, field.property.default ?? field.resolved.default);
      const value = fallback ?? (field.optional ? "nil" : undefined);
      return `${field.name === "default" ? "default value" : swiftIdentifier(field.name)}: ${field.swift}${field.optional ? "?" : ""}${value !== undefined ? ` = ${value}` : ""}`;
    });
    lines.push("", `    public init(${signature.join(", ")}) {`);
    for (const field of parameters) lines.push(`        self.${swiftIdentifier(field.name)} = ${field.name === "default" ? "value" : swiftIdentifier(field.name)}`);
    lines.push("    }");
    // An optional JSON field that is present but null decodes as `.null`, not nil.
    if (fields.some((field) => field.json && field.optional)) {
      lines.push("", `    private enum CodingKeys: String, CodingKey { case ${fields.map((field) => swiftIdentifier(field.name)).join(", ")} }`, "");
      lines.push("    public init(from decoder: any Decoder) throws {", "        let values = try decoder.container(keyedBy: CodingKeys.self)");
      for (const field of fields) {
        const name = swiftIdentifier(field.name);
        const base = field.constant !== undefined ? swiftType(context, schema, field.property) : field.swift;
        if (field.json && field.optional) lines.push(`        ${name} = values.contains(.${name}) ? try values.decode(JSONValue.self, forKey: .${name}) : nil`);
        else if (field.optional) lines.push(`        ${name} = try values.decodeIfPresent(${base}.self, forKey: .${name})`);
        else lines.push(`        ${name} = try values.decode(${base}.self, forKey: .${name})`);
      }
      lines.push("    }");
    }
    lines.push("}", "");
  }
  return lines.join("\n").replace(/\n+$/, "\n");
}

export function generateTypeScript(schemas) {
  const context = collect(schemas);
  const lines = [header("//").trimEnd(), ""];
  for (const type of context.types) {
    const { node } = type;
    const schema = sourceOf(context, schemas, type);
    lines.push(...doc(node.description, "", "ts"));
    if (type.kind === "alias") lines.push(`export type ${type.ts} = ${node["x-ts-type"]};`);
    else if (type.kind === "enum") lines.push(`export type ${type.ts} = ${node.enum.map((value) => JSON.stringify(value)).join(" | ")};`);
    else {
      lines.push(`export interface ${type.ts} {`);
      const required = new Set(node.required ?? []);
      for (const [name, property] of Object.entries(node.properties ?? {})) {
        if (property.$ref || context.typeOf(schema, property)?.node !== property) lines.push(...doc(property.description, "  ", "ts"));
        lines.push(`  ${name}${required.has(name) ? "" : "?"}: ${tsType(context, schema, property)};`);
      }
      lines.push("}");
    }
    lines.push("");
  }
  return lines.join("\n").replace(/\n+$/, "\n");
}

export async function generate() {
  const schemas = await Promise.all(schemaFiles.map(async (file) => JSON.parse(await readFile(path.join(root, file), "utf8"))));
  return { [outputs.swift]: generateSwift(schemas), [outputs.ts]: generateTypeScript(schemas) };
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const files = await generate();
  const stale = [];
  for (const [file, text] of Object.entries(files)) {
    const current = await readFile(path.join(root, file), "utf8").catch(() => null);
    if (current === text) continue;
    if (process.argv.includes("--check")) stale.push(file);
    else { await writeFile(path.join(root, file), text); console.log(`Wrote ${file}`); }
  }
  if (stale.length) {
    console.error(`Out of date: ${stale.join(", ")}. Run node scripts/generate-protocol.mjs and commit the result.`);
    process.exit(1);
  }
}
